<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1e293b;font-size:11px}h1{color:#0f766e;font-size:28px}table{width:100%;border-collapse:collapse;margin-top:30px}th,td{padding:12px 8px;border-bottom:1px solid #e2e8f0;text-align:left}.right{text-align:right}.total{font-weight:bold;font-size:16px}footer{margin-top:35px;color:#64748b}</style></head><body><h1>{{ $kind==='invoices'?'Invoice':'Bill' }} {{ $document->invoice_number ?? $document->bill_number }}</h1><h2>{{ $company->legal_name ?? $company->name }}</h2><p>{{ $company->email }}</p><p>{{ $document->customer->name ?? $document->supplier->name }}</p><p>Date: {{ $document->issue_date ?? $document->bill_date }} · Due: {{ $document->due_date }} · Status: {{ $document->status }}</p><table><thead><tr><th>Description</th><th>Quantity</th><th class="right">Unit price</th><th class="right">Tax</th><th class="right">Total</th></tr></thead><tbody>@foreach($document->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td class="right">{{ $item->unit_price }}</td><td class="right">{{ $item->tax_amount }}</td><td class="right">{{ $item->total }}</td></tr>@endforeach</tbody></table><p class="right">Subtotal {{ $document->subtotal }}</p><p class="right">Tax {{ $document->tax_total }}</p><p class="right total">Total {{ $document->currency }} {{ $document->total }}</p><p class="right">Outstanding {{ $document->outstanding }}</p><footer>{{ $document->notes }}</footer></body></html>
